"""Build a transparent *demonstration* dataset. NOT a validated AI-detector corpus."""
import csv
from pathlib import Path

human = [
'Я помню чудное мгновенье: передо мной явилась ты, как мимолетное виденье, как гений чистой красоты.',
'Мороз и солнце; день чудесный! Еще ты дремлешь, друг прелестный — пора, красавица, проснись.',
'У лукоморья дуб зеленый; златая цепь на дубе том: и днем и ночью кот ученый всё ходит по цепи кругом.',
'Буря мглою небо кроет, вихри снежные крутя; то, как зверь, она завоет, то заплачет, как дитя.',
'Зима недаром злится, прошла ее пора — весна в окно стучится и гонит со двора.',
'Люблю грозу в начале мая, когда весенний первый гром, как бы резвяся и играя, грохочет в небе голубом.',
'Есть в осени первоначальной короткая, но дивная пора — весь день стоит как бы хрустальный, и лучезарны вечера.',
'Умом Россию не понять, аршином общим не измерить: у ней особенная стать — в Россию можно только верить.',
'Белеет парус одинокий в тумане моря голубом! Что ищет он в стране далекой? Что кинул он в краю родном?',
'Выхожу один я на дорогу; сквозь туман кремнистый путь блестит; ночь тиха. Пустыня внемлет богу, и звезда с звездою говорит.',
'Когда волнуется желтеющая нива, и свежий лес шумит при звуке ветерка, и прячется в саду малиновая слива под тенью сладостной зеленого листка.',
'Ночевала тучка золотая на груди утеса-великана; утром в путь она умчалась рано, по лазури весело играя.',
'Не жалею, не зову, не плачу, всё пройдет, как с белых яблонь дым. Увяданья золотом охваченный, я не буду больше молодым.',
'Отговорила роща золотая березовым, веселым языком, и журавли, печально пролетая, уж не жалеют больше ни о ком.',
'Белая береза под моим окном принакрылась снегом, точно серебром. На пушистых ветках снежною каймой распустились кисти белой бахромой.',
'Черемуха душистая с весною расцвела и ветки золотистые, что кудри, завила.',
'Ночь, улица, фонарь, аптека, бессмысленный и тусклый свет. Живи еще хоть четверть века — всё будет так. Исхода нет.',
'О доблестях, о подвигах, о славе я забывал на горестной земле, когда твое лицо в простой оправе передо мной сияло на столе.',
'О, весна без конца и без краю — без конца и без краю мечта! Узнаю тебя, жизнь! Принимаю! И приветствую звоном щита!',
'Шепот, робкое дыханье, трели соловья, серебро и колыханье сонного ручья.',
'Я пришел к тебе с приветом, рассказать, что солнце встало, что оно горячим светом по листам затрепетало.',
'Это утро, радость эта, эта мощь и дня и света, этот синий свод, этот крик и вереницы, эти стаи, эти птицы, этот говор вод.',
'Я вас любил: любовь еще, быть может, в душе моей угасла не совсем; но пусть она вас больше не тревожит; я не хочу печалить вас ничем.',
'На холмах Грузии лежит ночная мгла; шумит Арагва предо мною. Мне грустно и легко; печаль моя светла; печаль моя полна тобою.'
]
# Procedural *synthetic* verses, NOT verified outputs of a generative language model.
starts = ['Под небом тихим свет рассвета', 'В сиянье звезд идет мечта', 'Когда на сердце тихо станет', 'Плывет туман над гладью вод', 'В ночной дали горят огни', 'И снова утро наступает', 'Где ветер шепчет о весне', 'В саду цветут надежды снова']
middles = ['душа находит вдохновенье', 'природа дарит нам тепло', 'в душе рождается стремленье', 'сердце верит в волшебство', 'и мир наполнен добротой', 'живут надежда и мечтанье', 'все мысли обретают свет', 'любовь ведет нас за собой']
ends = ['И каждый миг прекрасен снова, и счастье близко, как весна.', 'Пусть добрый свет наполнит сердце, и станет жизнь любви полна.', 'И звезды дарят нам надежду, и не исчезнет красота.', 'Пусть будет мир всегда чудесным, и не погаснет в нем мечта.', 'Ведь каждый день несет нам радость, и расцветает вновь душа.', 'И жизнь откроет двери счастья, когда наступит тишина.']
synthetic = [f'{starts[i % len(starts)]}, {middles[(i*3) % len(middles)]}. {ends[(i*5) % len(ends)]}' for i in range(48)]
p = Path(__file__).with_name('dataset.csv')
with p.open('w', encoding='utf-8', newline='') as f:
    w=csv.writer(f); w.writerow(['text','label','origin'])
    for t in human: w.writerow([t,'human','public_domain_poetry_excerpt'])
    for t in synthetic: w.writerow([t,'synthetic','procedural_template_not_llm'])
print('Wrote',p,'rows',len(human)+len(synthetic))
